\begin{defn}[دالة !!^{injective}]
تكون الدالة $f \colon A \rightarrow B$ \emph{!!{injective}} إذا وفقط إذا كان لكل
$y \in B$ عنصر~$x \in A$ واحد على الأكثر بحيث~$f(x) = y$. ونسمي
مثل هذه الدالة !!a{injection} من $A$ إلى~$B$.
\end{defn}

\begin{explain}
إذا أردت أن تبين أن $f$ هي !!a{injection}، فعليك أن تثبت،
لكل $x$ و$y$ من !!{element}s مجال $f$، أنه إذا كان $f(x)=f(y)$ فإن
$x=y$.
\end{explain}

\begin{defn}[دالة !!^{injective}]
الدالة $f \colon A \rightarrow B$ \emph{!!{injective}} إذا وفقط إذا
كان لكل $y \in B$ عنصر $x \in A$ واحد على الأكثر يحقق~$f(x) = y$.
وتسمى حينئذ !!a{injection} من $A$ إلى~$B$.
\end{defn}

\begin{explain}
ولإثبات أن $f$ هي !!a{injection} خذ !!{element}s $x$ و$y$ من مجال
$f$، وبيّن أن $f(x)=f(y)$ لا يكون إلا مع $x=y$.
\end{explain}
